    nx: size,
    ny: size,
    ex: DATA_TYPE[nx, ny] @ DRAM,
    ey: DATA_TYPE[nx, ny] @ DRAM,
    hz: DATA_TYPE[nx, ny] @ DRAM,
    _fict_: DATA_TYPE[tmax] @ DRAM,
):
    # Time-stepping loop. Each iteration depends on the previous time step,
    # so we keep this loop sequential for correctness.
    for t in seq(0, tmax):
        # Boundary condition on the first row of ey.
        # This loop writes a single row and walks j contiguously.
        for j in seq(0, ny):
            ey[0, j] = _fict_[t]

        # Update ey in the interior: i = 1..nx-1, j = 0..ny-1
        # Memory access pattern is row-major friendly: i is the outer loop,
        # j is innermost and walks contiguous elements in each row.
        for i in seq(1, nx):
            for j in seq(0, ny):
                ey[i, j] = ey[i, j] - 0.5 * (hz[i, j] - hz[i - 1, j])

        # Update ex in the interior: i = 0..nx-1, j = 1..ny-1
        for i in seq(0, nx):
            for j in seq(1, ny):
                ex[i, j] = ex[i, j] - 0.5 * (hz[i, j] - hz[i, j - 1])

        # Update hz in the interior: i = 0..nx-2, j = 0..ny-2
        # This stencil reads two neighboring values in each field and writes hz.
        for i in seq(0, nx - 1):
            for j in seq(0, ny - 1):
                hz[i, j] = hz[i, j] - 0.7 * (
                    ex[i, j + 1] - ex[i, j]
                    + ey[i + 1, j] - ey[i, j]
                )


