    # Parallelize the ey interior update over rows (i).
    # Body of the t-loop has the following structure:
    #   for j in ...
    #   for i in ...:  # ey update   <-- #0
    #   for i in ...:  # ex update   <-- #1
    #   for i in ...:  # hz update   <-- #2
    t_loop = p.find_loop("for t in _:_")
    ey_i = t_loop.body().find_loop("for i in _:_ #0")
    p = parallelize_loop(p, ey_i)

    # Parallelize the ex interior update over rows (i).
    t_loop = p.find_loop("for t in _:_")
    ex_i = t_loop.body().find_loop("for i in _:_ #1")
    p = parallelize_loop(p, ex_i)

