    t_loop = p.find_loop("for t in _:_")
    hz_i = t_loop.body().find_loop("for i in _:_ #2")
    p = parallelize_loop(p, hz_i)

    # Perform light-weight algebraic simplification after scheduling.
    p = simplify(p)
    return p


